-- Mod-authored World Congress splash descriptions, ru_RU overlay.
-- Baseline in CivVAccess_CongressDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_MISSING"] =
    "Для этого изображения нет описания."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_SPECIAL_SESSION_START_WORLD_CONGRESS"] =
    "Зал заседаний в разгаре работы, увиденный сзади, над головами сидящих. Впереди делегаты расположились вокруг длинного стола, покрытого красным сукном, на возвышении с ковровым покрытием, у каждого места лежит белый лист бумаги. Фигура в белом одеянии и белом головном уборе стоит во главе стола, обращаясь к залу; рядом с ней темнобородый мужчина. Аудитория сидит перед ними на деревянных стульях рядами, тюрбаны, тюбетейки и непокрытые головы вместе. Со стороны правой стены за происходящим наблюдают дополнительные зрители между бледными колоннами."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_FAIR"] =
    "Гигантское колесо обозрения уходит за верхний край картины справа, закрытые пассажирские кабинки свешиваются с его обода. Основание колеса скрывается за большой аркой из зелёного клёпаного железа, перекинутой через бледную стену с надписью FERRIS WHEEL. Внизу по широкой пыльной аллее идут посетители выставки: женщины в длинных платьях, мужчины в пальто, котелках и цилиндрах. Слева вдоль пути тянутся невысокие павильоны с расписными вывесками, а в глубине под бледно-голубым небом поднимается белый купольный зал."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_GAMES"] =
    "Первые секунды забега: четверо бегунов резко уходят со старта, опустив головы, на тёмной дорожке, которая дугой пересекает передний план. Слева за ними у стартовой черты стоит стартер в длинном белом пальто, его пистолет поднят и ещё дымится. Плотные трибуны заполняют весь задний план, толпа намечена мазками цвета. Белые складные вышки и высокие столбы выстроились вдоль дорожки справа, а за ними уходит зелень внутреннего поля."
